WITH requests AS MATERIALIZED (
 SELECT r.id,r.created_at,r.result,i.candidate_provenance->>'cohort' cohort,(i.candidate_provenance->>'profileCount')::int profile_count,(i.candidate_provenance->>'curatedCount')::int curated_count,g.id projection_id,g.profile_id,g.contribution_count,g.published_at,g.expires_at
 FROM recommendation_request r JOIN recommendation_served_item i ON i.request_id=r.id AND i.position=0 LEFT JOIN recommendation_profile_projection_generation g ON g.id=i.candidate_provenance->>'projectionId'
 WHERE r.surface_version='watch-for-you-v1' AND r.created_at>='2026-09-08T01:45:00Z' AND r.created_at<'2026-09-15T01:45:00Z'
)
SELECT cohort,profile_count,curated_count,count(*) requests,count(distinct profile_id) identifiable_profiles_via_projection,count(*) FILTER(WHERE projection_id IS NOT NULL) linked_projections,count(*) FILTER(WHERE projection_id IS NOT NULL AND expires_at<=created_at) expired_projection_at_request,count(*) FILTER(WHERE projection_id IS NOT NULL AND published_at>created_at) future_projection_at_request,percentile_cont(0.5) within group(order by contribution_count) median_contributions FROM requests GROUP BY 1,2,3 ORDER BY requests DESC;
WITH r AS MATERIALIZED (SELECT r.id,r.created_at FROM recommendation_request r WHERE r.surface_version='watch-for-you-v1' AND r.created_at>='2026-09-08T01:45:00Z' AND r.created_at<'2026-09-15T01:45:00Z')
SELECT i.candidate_generator,count(*) cards,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM recommendation_rendered_fact f WHERE f.item_id=i.id AND f.received_at<'2026-09-15T01:45:00Z')) rendered,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM recommendation_impression f WHERE f.item_id=i.id AND f.received_at<'2026-09-15T01:45:00Z')) impressed FROM r JOIN recommendation_served_item i ON i.request_id=r.id GROUP BY 1;
